begin;
alter table public.imaket_course_lessons add column summary text not null default '' check(length(summary)<=5000);
create table public.imaket_lesson_progress(user_id uuid not null references public.imaket_users(id),lesson_id uuid not null references public.imaket_course_lessons(id) on delete cascade,completed boolean not null default false,position_seconds integer not null default 0 check(position_seconds between 0 and 86400),updated_at timestamptz not null default now(),primary key(user_id,lesson_id));
alter table public.imaket_lesson_progress enable row level security;
grant select,insert,update on public.imaket_lesson_progress to authenticated;
create policy progress_read on public.imaket_lesson_progress for select to authenticated using(user_id=(select auth.uid()));
create policy progress_write on public.imaket_lesson_progress for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.imaket_course_lessons l where l.id=lesson_id and imaket_private.has_purchase(l.product_id)));
create policy progress_update on public.imaket_lesson_progress for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()) and exists(select 1 from public.imaket_course_lessons l where l.id=lesson_id and imaket_private.has_purchase(l.product_id)));
create index imaket_progress_lesson_idx on public.imaket_lesson_progress(lesson_id);
create policy imaket_paid_lesson_file on storage.objects for select to authenticated using(bucket_id='imaket-product-files' and exists(select 1 from public.imaket_course_lessons l where l.file_path=name and imaket_private.has_purchase(l.product_id)));
create table public.imaket_shipping_rates(id uuid primary key default gen_random_uuid(),creator_id uuid not null references public.imaket_creators(id),country_code text not null check(country_code ~ '^[A-Z]{2}$'),currency text not null check(currency ~ '^[A-Z]{3}$'),amount_cents bigint not null check(amount_cents between 0 and 10000000),delivery_estimate text not null check(length(delivery_estimate)<=200),active boolean not null default true,unique(creator_id,country_code,currency));
alter table public.imaket_shipping_rates enable row level security;
grant select on public.imaket_shipping_rates to anon,authenticated;
grant insert,update,delete on public.imaket_shipping_rates to authenticated;
create policy shipping_public on public.imaket_shipping_rates for select to anon using(active);
create policy shipping_visible on public.imaket_shipping_rates for select to authenticated using(active or imaket_private.owns_creator(creator_id));
create policy shipping_owner on public.imaket_shipping_rates for all to authenticated using(imaket_private.owns_creator(creator_id)) with check(imaket_private.creator_can_sell(creator_id));
create table public.imaket_shipments(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.imaket_orders(id),creator_id uuid not null references public.imaket_creators(id),carrier text not null check(length(carrier) between 1 and 100),tracking_number text not null check(length(tracking_number) between 1 and 200),tracking_url text not null default '' check(length(tracking_url)<=2000),status text not null check(status in ('processing','shipped','delivered')),updated_at timestamptz not null default now(),unique(order_id,creator_id));
alter table public.imaket_shipments enable row level security;
grant select,insert,update on public.imaket_shipments to authenticated;
create policy shipment_read on public.imaket_shipments for select to authenticated using(imaket_private.owns_creator(creator_id) or exists(select 1 from public.imaket_orders o where o.id=order_id and o.customer_id=(select auth.uid())));
create policy shipment_insert on public.imaket_shipments for insert to authenticated with check(imaket_private.creator_can_sell(creator_id) and exists(select 1 from public.imaket_order_items i join public.imaket_orders o on o.id=i.order_id join public.imaket_products p on p.id=i.product_id where i.order_id=imaket_shipments.order_id and i.creator_id=imaket_shipments.creator_id and o.status='paid' and p.type='Physical product'));
create policy shipment_edit on public.imaket_shipments for update to authenticated using(imaket_private.owns_creator(creator_id)) with check(imaket_private.creator_can_sell(creator_id) and exists(select 1 from public.imaket_order_items i join public.imaket_orders o on o.id=i.order_id join public.imaket_products p on p.id=i.product_id where i.order_id=imaket_shipments.order_id and i.creator_id=imaket_shipments.creator_id and o.status='paid' and p.type='Physical product'));
create index imaket_shipments_order_idx on public.imaket_shipments(order_id);
create index imaket_shipments_creator_idx on public.imaket_shipments(creator_id);
commit;
